<template>
  <WrfTaskConfig ref="baseConfig" :options="options" :data-source="dataSource" :initial-request="baseInitialRequest" :expert-mode="expertOpen" high-resolution hide-footer @update:expert-mode="value => expertOpen = value" @change="syncBase" @cancel="emit('cancel')">
    <template #additional>
      <section class="cfd-section config-card">
        <div class="step-title"><i>3</i><div><h3>选择结果</h3><p>系统自动完成区域天气模拟和局地 1 m 风场计算。</p></div></div>
        <el-alert v-if="initialContext?.source_wrf_task_id" type="info" :closable="false" title="当前为已有结果复用；如需从 27 km 开始，请使用新建高分任务入口。" />
        <el-form label-position="top"><div :class="['form-grid', expertOpen ? 'two' : 'three']">
          <el-form-item label="计算方式"><el-select v-model="form.parameterization_profile_id" placeholder="快速稳态风场（推荐）" @change="selectProfile"><el-option v-if="!parameterizationProfiles.length" label="快速稳态风场（推荐）" value="standard-rans-thermal/v1" /><el-option v-for="profile in parameterizationProfiles" :key="profile.id" :label="publicProfileLabel(profile)" :value="profile.id" /></el-select></el-form-item>
          <el-form-item label="地表处理">
            <el-radio-group v-if="expertOpen" v-model="form.surface_mode"><el-radio-button label="auto_flat">自动平坦地表</el-radio-button><el-radio-button label="reviewed_terrain">审核真实地形</el-radio-button></el-radio-group>
            <span v-else>{{ form.surface_mode === 'auto_flat' ? '简化地表（无需资料）' : '真实地形（已审核）' }}</span>
          </el-form-item>
          <el-form-item v-if="!expertOpen" label="输出高度"><el-select v-model="heightPreset" placeholder="常用高度（推荐）" @change="applyHeightPreset"><el-option label="常用高度（推荐）" value="common" /><el-option label="近地面与建筑高度" value="near_ground" /><el-option label="高层与风能高度" value="wind_energy" /></el-select></el-form-item>
        </div></el-form>
        <el-alert v-if="expertOpen && form.surface_mode === 'auto_flat'" type="info" :closable="false" title="系统将生成局地 z=0 m AGL 平坦地表，并从最内层 WRF 的 LU_INDEX/ZNT 自动推导粗糙度；产品会标记为理想化平坦地表。" />
        <div v-else-if="!expertOpen" class="plain-note">无需准备地形资料。结果适合查看局地风场分布，不表达真实建筑和山地细节。</div>
        <el-form v-else label-position="top"><el-form-item label="自动匹配真实地形"><span>{{ selectedAsset ? `${selectedAsset.label} · ${selectedAsset.version}` : '当前位置暂无符合条件的已审核地形' }}</span></el-form-item></el-form>
        <p v-if="expertOpen">1 m 表示发布采样间距；RANS 为独立快照，LES 为有限时段统计。</p>
        <p v-if="form.surface_mode === 'reviewed_terrain' && assetError" class="warning">{{ assetError }}</p>
        <div v-if="form.surface_mode === 'reviewed_terrain' && !selectedAsset" class="terrain-actions"><el-button @click="terrainDialog = true">提交地形资料审核</el-button><el-button text @click="submitForcingOnly">仅准备 forcing</el-button></div>
        <div v-if="expertOpen" class="form-grid two"><el-form-item label="AOI 宽度 (m)"><el-input-number v-model="form.aoi.width_m" :min="25" :max="2000" /></el-form-item><el-form-item label="AOI 高度 (m)"><el-input-number v-model="form.aoi.height_m" :min="25" :max="2000" /></el-form-item></div>
        <div v-if="!expertOpen" class="public-summary"><div><span>自动流程</span><b>区域天气 → 局地风场 → 可视化</b></div><div><span>发布范围</span><b>{{ form.aoi.width_m }} × {{ form.aoi.height_m }} m</b></div><div><span>结果时次</span><b>{{ form.cfd.solver_family === 'rans' ? `${form.cfd.rans?.selected_hours?.length || 0} 个代表时刻` : `${form.cfd.les?.episodes?.length || 0} 个统计时段` }}</b></div><div><span>地表</span><b>{{ form.surface_mode === 'auto_flat' ? '理想化简化地表' : '审核真实地形' }}</b></div></div>
        <div v-if="expertOpen" class="section-grid">
          <section v-if="expertOpen" class="config-card"><h3>求解器与计算域</h3><el-form label-position="top"><div class="form-grid two"><el-form-item label="求解器族"><el-radio-group v-model="form.cfd.solver_family" @change="normalizeSolver"><el-radio-button label="rans">RANS 稳态</el-radio-button><el-radio-button label="les">LES 瞬态</el-radio-button></el-radio-group></el-form-item><el-form-item label="物理模式"><el-radio-group v-model="form.cfd.thermal_mode"><el-radio-button label="thermal">热力浮力</el-radio-button><el-radio-button label="neutral">中性</el-radio-button></el-radio-group></el-form-item></div><div class="form-grid three"><el-form-item label="受管求解模板"><el-input v-model.trim="form.cfd.solver_template_id" /></el-form-item><el-form-item label="缓冲 B (m，留空自动)"><el-input-number v-model="form.cfd.domain.buffer_m" :min="1" :precision="1" controls-position="right" /></el-form-item><el-form-item label="顶部 AGL (m，留空自动)"><el-input-number v-model="form.cfd.domain.z_top_m_agl" :min="1" :precision="1" controls-position="right" /></el-form-item></div><div class="form-grid two"><el-form-item label="过渡单元数"><el-input-number v-model="form.cfd.domain.transition_cells" :min="3" :max="12" /></el-form-item><el-form-item label="表面细化 (m)"><el-input-number v-model="form.cfd.domain.surface_refinement_m" :min="0.1" :max="8" :precision="1" /></el-form-item></div></el-form></section>
          <section v-else class="config-card"><h3>求解方案已由常用配置填充</h3><p>当前方案：{{ activeProfile?.label || '标准业务 RANS' }}。求解器族、热力模式、缓冲和顶部高度由方案与地形特征自动确定；打开“专家配置”后可修改。</p><dl><div><dt>求解器</dt><dd>{{ form.cfd.solver_family.toUpperCase() }} · {{ form.cfd.thermal_mode === 'thermal' ? '热力' : '中性' }}</dd></div><div><dt>网格模板</dt><dd>{{ form.cfd.solver_template_id }}</dd></div><div><dt>外域</dt><dd>缓冲和顶部自动推导</dd></div></dl></section>
          <section class="config-card"><h3>发布采样高度 AGL (m)</h3><el-checkbox-group v-model="form.cfd.publication_heights_agl_m"><el-checkbox v-for="height in selectableHeights" :key="height" :label="height">{{ height }} m</el-checkbox></el-checkbox-group><p class="field-hint">实际 CFD 网格尺度会在每个高度记录 p50/p90；实体内部为 NoData 与掩膜。</p><el-divider /><h3>资源与发布</h3><p>原生结果在线保留 90 天后归档。配置未认证时，结果只能成为内部预览。</p></section>
        </div>
        <section v-if="expertOpen" class="config-card mesh-card"><h3>分级网格</h3><div class="mesh-head"><span>区域</span><span>最大单元 (m)</span><span>顶部 AGL (m)</span><span>水平外扩 (m)</span></div><div v-for="band in form.cfd.domain.mesh_bands" :key="band.name" class="mesh-row"><el-input v-model="band.name" /><el-input-number v-model="band.max_cell_m" :min="0.1" :max="64" :precision="1" /><el-input-number v-model="band.top_agl_m" :min="1" /><el-input-number v-model="band.horizontal_extension_m" :min="0" /></div></section>
        <div v-if="expertOpen" class="section-grid">
          <section class="config-card"><h3>WRF–CFD 边界与湍流</h3><el-form label-position="top"><el-form-item label="湍流来源"><el-radio-group v-model="form.cfd.turbulence.source"><el-radio-button label="diagnostic_closure">受控诊断闭合</el-radio-button><el-radio-button label="wrf_tke">直接 WRF TKE</el-radio-button></el-radio-group></el-form-item><div class="form-grid two"><el-form-item label="诊断闭合模板"><el-input v-model.trim="form.cfd.turbulence.closure_template_id" :disabled="form.cfd.turbulence.source === 'wrf_tke'" /></el-form-item><el-form-item label="flux-aware 边界模板"><el-input v-model.trim="form.cfd.turbulence.boundary_template_id" /></el-form-item></div></el-form><p class="warning">诊断闭合将强制要求 UST、HFX、PBLH；缺项、低风速或风向离散异常将转专家模板，绝不使用固定 10% 湍流强度。</p></section>
          <section v-if="form.cfd.solver_family === 'rans'" class="config-card"><h3>RANS 代表时次</h3><el-form label-position="top"><el-form-item label="选择方式"><el-radio-group v-model="form.cfd.rans.selection_mode"><el-radio label="system_recommended">系统推荐后确认</el-radio><el-radio label="user_confirmed">用户手选</el-radio></el-radio-group></el-form-item><el-form-item label="逐小时有效时次"><el-checkbox-group v-model="form.cfd.rans.selected_hours" :max="6"><el-checkbox v-for="hour in hourOptions" :key="hour" :label="hour">+{{ String(hour).padStart(2, '0') }} h</el-checkbox></el-checkbox-group></el-form-item></el-form></section>
          <section v-else class="config-card"><div class="section-title"><div><h3>LES 研究时段</h3><p>最多两个独立时段，发布统计场而非连续预报。</p></div><el-button size="small" :disabled="form.cfd.les.episodes.length >= 2" @click="addEpisode">添加时段</el-button></div><article v-for="(episode, index) in form.cfd.les.episodes" :key="index" class="episode"><div class="form-grid three"><el-form-item label="forcing 小时"><el-input-number v-model="episode.forcing_hour" :min="0" :max="durationHours" /></el-form-item><el-form-item label="预热 (s)"><el-input-number v-model="episode.spinup_seconds" :min="0" /></el-form-item><el-form-item label="统计窗口 (s)"><el-input-number v-model="episode.statistics_window_seconds" :min="60" /></el-form-item><el-form-item label="输出间隔 (s)"><el-input-number v-model="episode.output_interval_seconds" :min="1" /></el-form-item><el-form-item label="最大 CFL"><el-input-number v-model="episode.max_courant" :min="0.01" :max="1" :precision="2" /></el-form-item><el-form-item label="入口湍流"><el-select v-model="episode.inflow_method"><el-option label="合成湍流" value="synthetic_turbulence" /><el-option label="前驱 ABL" value="precursor_abl" /></el-select></el-form-item></div><el-button text type="danger" :disabled="form.cfd.les.episodes.length <= 1" @click="removeEpisode(index)">移除此时段</el-button></article></section>
        </div>
        <section v-if="expertOpen" class="config-card"><h3>边界与代表时段</h3><p>当前配置使用 {{ form.cfd.turbulence.source === 'wrf_tke' ? 'WRF TKE/QKE' : '受控诊断闭合' }}。{{ form.cfd.solver_family === 'les' ? `LES：${form.cfd.les?.episodes?.length || 0} 个有限统计时段。` : `RANS：${form.cfd.rans?.selected_hours?.length || 0} 个独立代表时次。` }}</p></section>

      </section>
    <el-dialog v-model="terrainDialog" title="提交地形与地表资产审核" width="680px">
      <p class="dialog-hint">先在上传工作台归档以下六类资料，再将每个文件的 UUID 填入对应栏位。未审核资产不会被任务使用。</p>
      <el-form label-position="top"><div class="form-grid three"><el-form-item label="资产 ID"><el-input v-model.trim="terrainForm.id" /></el-form-item><el-form-item label="名称"><el-input v-model.trim="terrainForm.label" /></el-form-item><el-form-item label="版本"><el-input v-model.trim="terrainForm.version" /></el-form-item></div><div class="form-grid two"><el-form-item label="SHA-256"><el-input v-model.trim="terrainForm.checksum_sha256" /></el-form-item><el-form-item label="CRS"><el-input v-model.trim="terrainForm.horizontal_crs" /></el-form-item></div><div class="form-grid four"><el-form-item label="垂直基准"><el-input v-model.trim="terrainForm.vertical_datum" /></el-form-item><el-form-item label="覆盖宽度 (m)"><el-input-number v-model="terrainForm.coverage_width_m" :min="1" /></el-form-item><el-form-item label="覆盖高度 (m)"><el-input-number v-model="terrainForm.coverage_height_m" :min="1" /></el-form-item><el-form-item label="Hchar (m)"><el-input-number v-model="terrainForm.hchar_m" :min="0" /></el-form-item></div><div class="form-grid two"><el-form-item label="覆盖中心纬度"><el-input-number v-model="terrainForm.coverage_center_lat" :precision="6" :min="-90" :max="90" /></el-form-item><el-form-item label="覆盖中心经度"><el-input-number v-model="terrainForm.coverage_center_lon" :precision="6" :min="-180" :max="180" /></el-form-item></div><el-form-item label="控制点误差 (m)"><el-input-number v-model="terrainForm.control_point_error_m" :min="0" :precision="2" /></el-form-item><div class="form-grid two"><el-form-item v-for="kind in assetKindOptions" :key="kind" :label="`${assetKindLabels[kind]} file UUID`"><el-input v-model.trim="terrainForm.file_map[kind]" /></el-form-item></div></el-form>
      <template #footer><el-button @click="terrainDialog = false">取消</el-button><el-button type="primary" :loading="terrainSubmitting" @click="submitTerrain">提交审核</el-button></template>
    </el-dialog>


      <footer class="highres-footer"><span>{{ expertOpen ? `${durationHours} 小时 · 27 km → 1 m · ${form.aoi.width_m} × ${form.aoi.height_m} m` : `${durationHours} 小时 · 局地风场 ${form.aoi.width_m} × ${form.aoi.height_m} m · ${form.cfd.publication_heights_agl_m.length} 个高度` }}</span><el-button type="primary" size="large" :disabled="form.surface_mode === 'reviewed_terrain' && !selectedAsset" :loading="submitting || validating" @click="submitFullChain">检查并创建高分任务</el-button></footer>
    </template>
  </WrfTaskConfig>
</template>
<script setup>
import { computed, onMounted, onBeforeUnmount, reactive, ref, watch } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import { getDownscaleTemplates, getDownscaleTerrainAssets, resolveDownscaleTerrainAssets, submitDownscaleTerrainAsset, validateDownscaleTask } from "../api.js";
import { highresDomains } from "../utils/highresGeometry.js";
import WrfTaskConfig from "./WrfTaskConfig.vue";

const props = defineProps({ options: Object, dataSource: { type: String, default: "gfs" }, submitting: Boolean, initialContext: { type: Object, default: null } });
const emit = defineEmits(["submit", "cancel"]);
const baseConfig = ref(null);
let baseRequest = null;
const baseInitialRequest = computed(() => props.initialContext?.start_time ? { start_time: props.initialContext.start_time, end_time: props.initialContext.end_time, center: props.initialContext.center } : undefined);
function syncBase(value) {
  baseRequest = value;
  form.start_time = value.start_time.slice(0, 16);
  form.end_time = value.end_time.slice(0, 16);
  form.aoi.center_lat = value.center.lat;
  form.aoi.center_lon = value.center.lon;
  form.wrf.boundary_source = value.data_source;
  for (const key of ["mp_physics", "ra_lw_physics", "ra_sw_physics", "bl_pbl_physics", "sf_sfclay_physics", "sf_surface_physics"]) form.wrf.physics[key] = value.physics[key];
  form.wrf.physics.radt_minutes = value.physics.radt;
  form.wrf.physics.cu_physics_by_domain = [...(value.physics.cu_physics_by_domain || [value.physics.cu_physics, 0, 0, 0]).slice(0, 4), 0, 0, 0, 0];
}
function submitFullChain() { form.execution_scope = "wrf_cfd"; return preflight(); }
function submitForcingOnly() { form.execution_scope = "forcing_only"; form.upstream_mode = "full_chain"; return preflight(); }

const assets = ref([]);
const loadingAssets = ref(false);
const validating = ref(false);
const assetError = ref("");
const terrainResolution = ref(null);
const terrainDialog = ref(false);
const terrainSubmitting = ref(false);
const parameterizationProfiles = ref([]);
const expertOpen = ref(false);
const heightPreset = ref("common");
const assetKindOptions = ["dtm", "dsm", "buildings", "stl", "land_cover", "surface_properties"];
const assetKindLabels = { dtm: "裸地高程 DTM", dsm: "地表高程 DSM", buildings: "建筑矢量", stl: "闭合 CFD 地表 STL", land_cover: "土地覆盖", surface_properties: "地表属性 JSON" };
const terrainForm = reactive({ id: "", label: "", version: "v1", checksum_sha256: "", horizontal_crs: "", vertical_datum: "", coverage_width_m: 0, coverage_height_m: 0, coverage_center_lat: null, coverage_center_lon: null, hchar_m: 0, control_point_error_m: 0, file_map: Object.fromEntries(assetKindOptions.map(kind => [kind, ""])) });
const roundedHour = new Date();
roundedHour.setUTCMinutes(0, 0, 0);
const hourOptions = computed(() => Array.from({ length: durationHours.value + 1 }, (_, index) => index));
const selectableHeights = [2, 5, 10, 20, 40, 80, 120, 150, 200, 300];
const defaultDomains = highresDomains;
const defaultWrf = () => ({ domains: defaultDomains(), e_vert: 88, time_step_seconds: 0.5, spinup_hours: 6, boundary_source: "gfs", ndown_template_id: "ndown-normal-27km-to-10m/v1", output_variables: ["U", "V", "W", "T", "P", "PB", "PH", "PHB", "QVAPOR", "QKE", "HGT", "UST", "HFX", "PBLH", "LU_INDEX", "ZNT"], physics: { profile_id: "wrf-3d-tke-les/v1", mp_physics: 8, ra_lw_physics: 4, ra_sw_physics: 4, bl_pbl_physics: 2, sf_sfclay_physics: 2, sf_surface_physics: 2, cu_physics_by_domain: [3, 0, 0, 0, 0, 0, 0, 0], radt_minutes: 1 } });
const defaultCfd = () => ({ solver_family: "rans", thermal_mode: "thermal", solver_template_id: "thermal-rans-graded/v2", publication_heights_agl_m: [10, 40, 80, 120, 200], turbulence: { source: "diagnostic_closure", closure_template_id: "mo-abl-diagnostic/v2", boundary_template_id: "wrf-flux-aware-mixed-open/v2" }, domain: { buffer_m: null, z_top_m_agl: null, transition_cells: 3, surface_refinement_m: 1, mesh_bands: [{ name: "publication_core", max_cell_m: 1, top_agl_m: 16, horizontal_extension_m: 0 }, { name: "near_buffer", max_cell_m: 2, top_agl_m: 48, horizontal_extension_m: 50 }, { name: "mid_buffer", max_cell_m: 4, top_agl_m: 112, horizontal_extension_m: 150 }, { name: "outer_domain", max_cell_m: 8, top_agl_m: 192, horizontal_extension_m: 0 }, { name: "upper_domain", max_cell_m: 16, top_agl_m: 384, horizontal_extension_m: 0 }] }, rans: { selected_hours: [0, 12, 24, 36, 48], selection_mode: "system_recommended" }, les: null });
const form = reactive({ execution_scope: "wrf_cfd", upstream_mode: "full_chain", surface_mode: "auto_flat", parameterization_profile_id: "standard-rans-thermal/v1", start_time: roundedHour.toISOString().slice(0, 16), end_time: new Date(roundedHour.getTime() + 48 * 3600 * 1000).toISOString().slice(0, 16), terrain_asset_id: "", source_wrf_task_id: "", source_forcing_task_id: "", aoi: { center_lat: 32.06016, center_lon: 118.80017, horizontal_crs: "EPSG:32650", center_x_m: null, center_y_m: null, width_m: 500, height_m: 500 }, wrf: defaultWrf(), cfd: defaultCfd(), upstream_artifact_id: "", upstream_content_sha256: "", certification_profile_id: "" });
const readyAssets = computed(() => terrainResolution.value?.items?.filter(asset => asset.suitability === "ready") || []);
const selectedAsset = computed(() => (terrainResolution.value?.items || []).find(asset => asset.id === form.terrain_asset_id));
const activeProfile = computed(() => parameterizationProfiles.value.find(profile => profile.id === form.parameterization_profile_id) || null);

const durationHours = computed(() => {
  const start = Date.parse(`${form.start_time}:00Z`);
  const end = Date.parse(`${form.end_time}:00Z`);
  const hours = (end - start) / 3600000;
  return Number.isFinite(hours) ? hours : 0;
});
const derivedBufferM = computed(() => Math.max(300, Number(form.cfd.domain.buffer_m) || 0, 15 * Number(selectedAsset.value?.hchar_m || 0)));
const isCfdHandoff = computed(() => form.execution_scope === "wrf_cfd" && form.upstream_mode === "reuse_10m");
const footerHint = computed(() => form.execution_scope === "forcing_only" ? `本任务生成连续 ${durationHours.value} h、${durationHours.value + 1} 时次的约 10 m 三维 forcing（实际 12.345679 m）；不会启动 CFD。` : (form.upstream_mode === "full_chain" ? "一次提交后自动创建上游并完成 d04→d08 forcing、1 m CFD、质量门和可视化。" : (form.cfd.solver_family === "les" ? "LES 将发布有限统计时段；入口来自已完成 d08 forcing。" : "RANS 将运行用户确认的 1–6 个独立稳态时次；入口来自已完成 d08 forcing。")));

let terrainResolveTimer = null;
let terrainResolveGeneration = 0;
watch(() => form.terrain_asset_id, id => { const asset = (terrainResolution.value?.items || assets.value).find(item => item.id === id); if (asset) form.aoi.horizontal_crs = asset.horizontal_crs; });
watch(() => form.surface_mode, mode => { if (mode === "auto_flat") form.terrain_asset_id = ""; else resolveTerrainCoverage(); });
watch(() => form.execution_scope, scope => { if (scope === "forcing_only") { form.upstream_mode = "full_chain"; form.source_forcing_task_id = ""; } });
watch(() => [form.start_time, form.end_time], () => {
  normalizeSamplingWindow();
});
watch(() => [form.aoi.center_lat, form.aoi.center_lon, form.aoi.width_m, form.aoi.height_m, form.aoi.horizontal_crs], () => { clearTimeout(terrainResolveTimer); terrainResolveGeneration++; terrainResolution.value = null; form.terrain_asset_id = ""; terrainResolveTimer = setTimeout(resolveTerrainCoverage, 180); });
watch(() => form.wrf.domains.length, syncCumulus);

function syncCumulus() { const values = form.wrf.physics.cu_physics_by_domain; while (values.length < form.wrf.domains.length) values.push(0); form.wrf.physics.cu_physics_by_domain = values.slice(0, form.wrf.domains.length); }
function normalizeSamplingWindow() { const duration = Math.max(0, Math.min(168, durationHours.value)); if (form.cfd.rans) { if (form.cfd.rans.selection_mode === "system_recommended") form.cfd.rans.selected_hours = [...new Set([0, Math.round(duration / 2), duration])]; form.cfd.rans.selected_hours = form.cfd.rans.selected_hours.filter(hour => hour <= duration); if (!form.cfd.rans.selected_hours.length) form.cfd.rans.selected_hours = [0]; } if (form.cfd.les) form.cfd.les.episodes.forEach(episode => { episode.forcing_hour = Math.min(duration, Number(episode.forcing_hour) || 0); }); }
function normalizeSolver() { if (form.cfd.solver_family === "rans") { form.cfd.rans ||= { selected_hours: [0, 12, 24, 36, 48], selection_mode: "system_recommended" }; form.cfd.les = null; } else { form.cfd.rans = null; form.cfd.les ||= { episodes: [{ forcing_hour: 12, spinup_seconds: 600, statistics_window_seconds: 1800, output_interval_seconds: 60, max_courant: 0.8, inflow_method: "synthetic_turbulence", inflow_template_id: "digital-filter-inflow/v1" }] }; } normalizeSamplingWindow(); }
function addEpisode() { if (form.cfd.les.episodes.length < 2) form.cfd.les.episodes.push({ forcing_hour: Array.from({length: durationHours.value + 1}, (_, i) => i).find(hour => !form.cfd.les.episodes.some(e => e.forcing_hour === hour)) ?? 0, spinup_seconds: 600, statistics_window_seconds: 1800, output_interval_seconds: 60, max_courant: 0.8, inflow_method: "synthetic_turbulence", inflow_template_id: "digital-filter-inflow/v1" }); }
function removeEpisode(index) { if (form.cfd.les.episodes.length > 1) form.cfd.les.episodes.splice(index, 1); }
function deepClone(value) { return JSON.parse(JSON.stringify(value)); }
function publicProfileLabel(profile) {
  const family = String(profile?.cfd?.solver_family || "rans").toLowerCase();
  if (family === "les") return "精细瞬态研究";
  return profile?.recommended ? "快速稳态风场（推荐）" : (profile?.label || "稳态风场");
}
function applyHeightPreset(value) {
  const presets = { common: [10, 40, 80, 120, 200], near_ground: [2, 5, 10, 20, 40], wind_energy: [40, 80, 120, 150, 200] };
  form.cfd.publication_heights_agl_m = [...(presets[value] || presets.common)];
}
function selectProfile(profileId) { const profile = parameterizationProfiles.value.find(item => item.id === profileId); if (!profile) return; form.parameterization_profile_id = profile.id; form.cfd = deepClone(profile.cfd); normalizeSolver(); normalizeSamplingWindow(); syncCumulus(); }
function applyInitialContext(context) { if (!context) return; expertOpen.value = true; if (context.execution_scope) form.execution_scope = context.execution_scope; if (context.upstream_mode) form.upstream_mode = context.upstream_mode; if (context.surface_mode) form.surface_mode = context.surface_mode; if (context.parameterization_profile_id) form.parameterization_profile_id = context.parameterization_profile_id; if (context.start_time) form.start_time = String(context.start_time).replace("Z", "").slice(0, 16); if (context.end_time) form.end_time = String(context.end_time).replace("Z", "").slice(0, 16); if (context.source_wrf_task_id) form.source_wrf_task_id = context.source_wrf_task_id; if (context.source_forcing_task_id) form.source_forcing_task_id = context.source_forcing_task_id; if (context.center?.lat != null) form.aoi.center_lat = Number(context.center.lat); if (context.center?.lon != null) form.aoi.center_lon = Number(context.center.lon); }
async function resolveTerrainCoverage() { if (form.surface_mode === "auto_flat") { terrainResolution.value = null; form.terrain_asset_id = ""; return; } if (!form.aoi.horizontal_crs) return; const generation = ++terrainResolveGeneration; try { const result = await resolveDownscaleTerrainAssets(deepClone(form.aoi)); if (generation !== terrainResolveGeneration) return; terrainResolution.value = result; assetError.value = ""; const available = readyAssets.value; if (form.terrain_asset_id && !available.some(asset => asset.id === form.terrain_asset_id)) form.terrain_asset_id = ""; if (!form.terrain_asset_id && terrainResolution.value?.recommended_asset_id) form.terrain_asset_id = terrainResolution.value.recommended_asset_id; } catch (error) { assetError.value = error.message || "无法评估地形资产覆盖"; } }
async function loadAssets() { loadingAssets.value = true; assetError.value = ""; try { const result = await getDownscaleTerrainAssets(); assets.value = result?.items || []; await resolveTerrainCoverage();  } catch (error) { assetError.value = error.message; } finally { loadingAssets.value = false; } }
async function submitTerrain() { const asset_files = assetKindOptions.map(kind => ({ kind, file_uuid: terrainForm.file_map[kind]?.trim() })).filter(item => item.file_uuid); if (asset_files.length !== assetKindOptions.length) return ElMessage.warning("请填写全部六类地形与地表文件 UUID"); const source_file_uuids = asset_files.map(item => item.file_uuid); const value = deepClone(terrainForm); delete value.file_map; terrainSubmitting.value = true; try { await submitDownscaleTerrainAsset({ ...value, source_file_uuids, asset_files, source: "backend_upload" }); terrainDialog.value = false; ElMessage.success("地形资产已提交审核，审核通过后会出现在资产列表"); } catch (error) { ElMessage.error(error.message); } finally { terrainSubmitting.value = false; } }
async function loadTemplates() { try { const templates = await getDownscaleTemplates(); parameterizationProfiles.value = templates?.parameterization?.profiles || []; if (templates?.defaults?.wrf) form.wrf = templates.defaults.wrf; if (templates?.defaults?.cfd) form.cfd = templates.defaults.cfd; const defaultProfile = templates?.parameterization?.default_profile_id || form.parameterization_profile_id; if (parameterizationProfiles.value.some(profile => profile.id === form.parameterization_profile_id)) selectProfile(form.parameterization_profile_id); else if (parameterizationProfiles.value.some(profile => profile.id === defaultProfile)) selectProfile(defaultProfile); else { form.parameterization_profile_id = defaultProfile; normalizeSolver(); syncCumulus(); } } catch { /* The typed local defaults keep offline authoring possible. */ } }
function payload() { const value = deepClone(form); value.start_time = `${value.start_time}:00Z`; value.end_time = `${value.end_time}:00Z`; if (!props.initialContext?.source_wrf_task_id) { value.upstream_mode = "full_chain"; value.source_wrf_task_id = null; value.source_forcing_task_id = null; } value.certification_profile_id ||= undefined; if (value.upstream_mode !== "full_chain") { value.source_wrf_task_id ||= undefined; value.source_forcing_task_id ||= undefined; } if (value.surface_mode === "auto_flat") delete value.terrain_asset_id; if (value.execution_scope === "forcing_only") { delete value.terrain_asset_id; value.source_forcing_task_id = null; delete value.parameterization_profile_id; } if (value.upstream_mode === "full_chain" || value.upstream_mode === "reuse_10m") { delete value.upstream_artifact_id; delete value.upstream_content_sha256; } return value; }
function frontendChecks() { if (!form.aoi.horizontal_crs) throw new Error("请填写 AOI 水平 CRS"); if (!Number.isInteger(durationHours.value) || durationHours.value < 1 || durationHours.value > 168) throw new Error("高分任务时间窗口必须为 1–168 个整小时"); if (!["gfs", "ecmwf"].includes(form.wrf.boundary_source)) throw new Error("高分一键上游目前只支持 GFS 或 ECMWF 边界资料"); if (form.execution_scope === "forcing_only") return; if (!form.parameterization_profile_id) throw new Error("请选择一个高分参数化方案"); if (form.upstream_mode === "reuse_10m" && (!form.source_forcing_task_id || !form.source_wrf_task_id)) throw new Error("复用 forcing 需要绑定已完成的 forcing 任务和普通 WRF 上游"); if (form.surface_mode === "reviewed_terrain" && !form.terrain_asset_id) throw new Error("真实地形模式需要选择已审核地形，或切换为自动平坦地表"); if (form.surface_mode === "reviewed_terrain" && !readyAssets.value.some(asset => asset.id === form.terrain_asset_id)) throw new Error("所选地形没有通过当前 AOI 的覆盖预检"); if (!form.cfd.publication_heights_agl_m.length) throw new Error("至少选择一个发布高度"); if (form.cfd.solver_family === "rans" && !form.cfd.rans.selected_hours.length) throw new Error("RANS 至少选择一个代表时次"); }
async function preflight() { if (validating.value || props.submitting) return; try { const baseError = baseConfig.value?.validateForm(); if (baseError) throw new Error(baseError); if (baseRequest) syncBase(baseRequest); frontendChecks(); validating.value = true; const checked = await validateDownscaleTask(payload()); const domain = checked.cfd_domain || {}; const review = domain.review_reasons || []; const forcingOnly = form.execution_scope === "forcing_only"; const sampling = checked.sampling?.solver_family === "les" ? `${checked.sampling.episodes?.length || 0} 个 LES 统计时段` : `${checked.sampling?.selected_valid_times?.length || 0} 个 RANS 独立快照`; const surfaceLabel = checked.surface?.mode === "auto_flat" ? "自动平坦地表（WRF LU_INDEX/ZNT 粗糙度）" : `审核真实地形 ${checked.surface?.terrain_asset_id || ""}`; const summary = forcingOnly ? `产品：约 10 m 三维 forcing（实际 12.345679 m） · ${checked.product?.valid_time_count || 49} 个逐小时时次\n范围：仅中尺度 forcing，不生成 CFD 网格或 1 m 产品\n${review.length ? `\n将进入审核：${review.join("；")}` : "\n可进入受管 forcing 队列"}` : `发布 AOI：${checked.product?.width_m} m × ${checked.product?.height_m} m · 1 m 采样\n地表：${surfaceLabel}\n支撑域：${domain.width_m} m × ${domain.height_m} m · 缓冲 ${domain.buffer_m} m\n预计网格：${Number(domain.estimated_cells || 0).toLocaleString()} cells · 内存 ${domain.estimated_memory_gib} GiB · 磁盘 ${domain.estimated_disk_gib} GiB\n微尺度合同：${sampling}\n${review.length ? `\n将进入审核：${review.join("；")}` : "\n可进入自动受管队列"}`; await ElMessageBox.confirm(`${summary}\n\n认证状态：${checked.certification?.status === "certified" ? "认证配置，可在质量门后正式发布" : "自定义研究配置，仅内部预览"}`, forcingOnly ? "确认约 10 m forcing 任务" : "确认专业降尺度任务", { type: review.length ? "warning" : "info", confirmButtonText: review.length ? "提交审核" : "确认提交", cancelButtonText: "返回修改" }); emit("submit", { ...payload(), confirmation_token: checked.confirmation_token }); } catch (error) { if (error !== "cancel" && error !== "close") ElMessage.error(error.message); } finally { validating.value = false; } }
watch(() => props.initialContext, applyInitialContext, { immediate: true, deep: true });
onBeforeUnmount(() => clearTimeout(terrainResolveTimer));
onMounted(async () => { await loadTemplates(); if (baseRequest) syncBase(baseRequest); await loadAssets(); });
</script>

